package com.elitedarkkaiser.nubialy;
import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w440dp-h900dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class SettingsEditorTest {
 @Test public void layoutSelectionIsDraftOnlyAndSurvivesRecreation()throws Exception {var ctl=Robolectric.buildActivity(SettingsEditorActivity.class).setup();var a=ctl.get();ReflectionHelpers.callInstanceMethod(a,"open",ReflectionHelpers.ClassParameter.from(String.class,"layout"));a.findViewById(android.R.id.content).findViewWithTag("settings-layout:1").performClick();ExecutorService worker=ReflectionHelpers.getField(a,"worker");worker.submit(()->{}).get(3,TimeUnit.SECONDS);assertEquals(1,SettingsPreferences.draft(a).layout());assertNull(SettingsPreferences.active(a));ctl.recreate();assertNotNull(ctl.get().findViewById(android.R.id.content).findViewWithTag("settings-layout:1"));ctl.get().onBackPressed();assertEquals("",ReflectionHelpers.getField(ctl.get(),"page"));ctl.pause().stop().destroy();}
 @Test public void renderSettingsLayoutsAndRealHomeCards()throws Exception {var ctl=Robolectric.buildActivity(SettingsEditorActivity.class).setup();var a=ctl.get();ReflectionHelpers.callInstanceMethod(a,"open",ReflectionHelpers.ClassParameter.from(String.class,"layout"));View root=a.findViewById(android.R.id.content);render(root,"settings-layouts");var s=SettingsStyle.DEFAULT.with(0,1).with(1,1).resolve(SurfaceStyle.STOCK,false);int[] clicks={0};boolean[] gate={true};var home=new SettingsHomeView(a,s,List.of(List.of(new SettingsHomeView.Entry("network","Network & internet","Wi-Fi, SIM & mobile",null,()->clicks[0]++),new SettingsHomeView.Entry("connected","Connected devices","Bluetooth, pairing",null,()->clicks[0]++)),List.of(new SettingsHomeView.Entry("personalize","Personalize","Colors and themes",null,()->clicks[0]++))),"Profile",()->{},()->{},()->gate[0]);render(home,"settings-rising-home");assertEquals(0,clicks[0]);View row=find(home,"Network & internet");assertNotNull(row);row.performClick();assertEquals(1,clicks[0]);gate[0]=false;row.performClick();assertEquals(1,clicks[0]);ctl.pause().stop().destroy();}
 @Test public void allSharedCardEffectsRespectCanvasAndRevocation(){for(int id:new int[]{0,1,2,3,4,5,6,7,101,102,103,104,105,201,202,203,204,205,206}){boolean[] allowed={true};var d=new SettingsCardDrawable(SettingsStyle.DEFAULT.with(12,id),1,()->allowed[0]);d.setBounds(10,10,150,90);Bitmap b=Bitmap.createBitmap(160,100,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);int saves=c.getSaveCount();d.draw(c);assertEquals(saves,c.getSaveCount());assertEquals(0,b.getPixel(0,0));allowed[0]=false;b.eraseColor(Color.TRANSPARENT);d.draw(c);int[] pixels=new int[16000];b.getPixels(pixels,0,160,0,0,160,100);assertTrue(java.util.Arrays.stream(pixels).allMatch(v->v==0));b.recycle();}}
 @Test public void restoreStopsOnlySettingsProfile(){var c=RuntimeEnvironment.getApplication();var s=SettingsStyle.DEFAULT.with(0,1);assertTrue(SettingsPreferences.save(c,s));assertNull(SettingsPreferences.active(c));assertTrue(SettingsPreferences.activate(c,s));assertEquals(s,SettingsPreferences.active(c));assertTrue(SettingsPreferences.stop(c));assertNull(SettingsPreferences.active(c));assertEquals(s,SettingsPreferences.draft(c));}
 @Test public void homeScrollCanBeRestoredAfterNativeNavigation()throws Exception {var c=RuntimeEnvironment.getApplication();var items=new ArrayList<SettingsHomeView.Entry>();for(int i=0;i<30;i++)items.add(new SettingsHomeView.Entry("entry"+i,"Setting "+i,"Summary",null,()->{}));var home=new SettingsHomeView(c,SettingsStyle.DEFAULT,List.of(items),"Profile",()->{},()->{},()->true);home.measure(View.MeasureSpec.makeMeasureSpec(440,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY));home.layout(0,0,440,900);home.restoreScrollPosition(300);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertEquals(300,home.scrollPosition());}
 private View find(View v,String label){if(label.contentEquals(v.getContentDescription()==null?"":v.getContentDescription()))return v;if(v instanceof ViewGroup g)for(int i=0;i<g.getChildCount();i++){View found=find(g.getChildAt(i),label);if(found!=null)return found;}return null;}
 private void render(View root,String name)throws Exception {root.measure(View.MeasureSpec.makeMeasureSpec(440,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(900,View.MeasureSpec.EXACTLY));root.layout(0,0,440,900);Bitmap b=Bitmap.createBitmap(440,900,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));File f=new File("build/editor-previews/"+name+".png");f.getParentFile().mkdirs();try(var out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
